import io
data = b"REC1:alpha\nREC2:beta\nREC3:gamma\n"
INDEX = {"REC1": 0, "REC2": 10, "REC3": 19}
f = io.BytesIO(data)
def fetch(rid):
    f.seek(INDEX[rid])
    return f.readline().decode().strip()
print(fetch("REC2"))

