doc = {"collection": [{"title": "A"}, {"title": "B"}]}
def getpath(doc, path):
    node = doc
    for step in path.split("."):
        if "[" in step:
            key, idx = step[:-1].split("[")
            node = node[key][int(idx)]
        else:
            node = node[step]
    return node
print(getpath(doc, "collection[1].title"))

